/* Generic accessors — map assets are in map_assets.h (1280x720 stretched) */
#define CHAR_ANIM_RANGE(cid, state, dir) (anim_ranges[cid][(state)*3+(dir)])
#define STATE_RUN  0
#define STATE_JUMP 1
#define STATE_FALL 2
#define STATE_LAND 3
#define DIR_LEFT   0
#define DIR_CENTER 1
#define DIR_RIGHT  2

#endif /* ASSETS_DATA_H */
